// Kártya-galéria: a bérlési modell-oldalak (dist/berelheto-auto/<slug>-berles/) valódi sajtófotói
function buildGallery() {
  const out = {};
  const dir = 'dist/berelheto-auto';
  if (!fs.existsSync(dir)) return out;
  for (const d of fs.readdirSync(dir)) {
    const f = dir + '/' + d + '/index.html';
    if (!d.endsWith('-berles') || !fs.existsSync(f)) continue;
    const h = fs.readFileSync(f, 'utf8');
    if (h.length < 5000) continue; // átirányító csonk
    const urls = [];
    const re = /<img[^>]*class="(cd-hero-car|cd-shot)[^"]*"[^>]*src="(\/[^"]+\.(?:webp|jpe?g|png))"/g;
    let m;
    while ((m = re.exec(h))) { const u = m[2]; if (u.startsWith('/berles/') || urls.includes(u)) continue; urls.push(u); }
    if (urls.length) out[d.replace(/-berles$/, '')] = urls.slice(0, 8);
  }
  return out;
}
