const FILES = ['dist/autoink/index.html','dist/en/autoink/index.html'];
const ANCHOR = '<div class="autok-panel" id="panel-berelheto">';
let done = 0;
for (const f of FILES) {
  if (!fs.existsSync(f)) continue;
  let h = fs.readFileSync(f, 'utf8');
  if (h.indexOf('sub-filters') > -1) { console.log('[abo] mar beszurva: ' + f); continue; }
  const i = h.indexOf(ANCHOR);
  if (i < 0) { console.log('[abo] nincs panel-berelheto: ' + f); continue; }
  const at = i + ANCHOR.length;
  h = h.slice(0, at) + BENEFITS + '<script>window.__ABGAL=' + JSON.stringify(GAL).replace(/</g, '\\u003c') + ';</script>' + SEC + h.slice(at);
  if (h.indexOf(OLD_SUB) > -1) h = h.replace(OLD_SUB, NEW_SUB);
  const hb = h.indexOf('data-hero="berelheto"');
  if (hb > -1) { const bi = h.indexOf(BERL, hb); if (bi > -1 && bi < hb + 1600) { let j = bi; while (j > 0 && h[j-1] >= '0' && h[j-1] <= '9') j--; const numStr = h.slice(j, bi); if (numStr) { const n = parseInt(numStr, 10) + SUB_TOTAL; h = h.slice(0, j) + n + h.slice(bi); } } }
  { const _hb = h.indexOf('data-hero="berelheto"'); if (_hb > -1) { const _seg = h.slice(_hb, _hb + 600); const _m = _seg.match(/<img class="brand-logo"[^>]*>/); if (_m) { h = h.slice(0, _hb) + _seg.replace(_m[0], STRIP) + h.slice(_hb + 600); } } }
  // ---- Prémium fül: a raktári bérelhető autók külön fülre; a Bérelhető fülön csak az új autós kínálat ----
  {
    const tabRe = /(<button class="autok-tab" data-tab="berelheto" data-group="berles" type="button" hidden>)Bérelhető \((\d+)\)(<\/button>)/;
    const tm = h.match(tabRe);
    const pi = h.indexOf(ANCHOR);
    const be = h.indexOf('<div class="autok-panel" id="panel-berbeadva">', pi);
    if (tm && pi > -1 && h.indexOf('id="panel-premium"') < 0) {
      const cnt = '<div class="count">' + tm[2] + ' autó</div>';
      const ci = h.lastIndexOf(cnt, be > -1 ? be : h.length);
      if (ci > pi) {
        const PREM = '<div class="rb-prem" id="premium"><h3>Prémium autók raktárról <span>(' + tm[2] + ')</span></h3><p>Saját készletű, azonnal elvihető prémium autók havidíjas bérletre — 6 hónaptól, 2 000 vagy 3 000 km/hó kerettel. Az árak nettó havidíjak.</p></div>'
          + '<style>#panel-berelheto .rb-prem{margin:46px 0 16px;padding-top:30px;border-top:1px solid #e6eaf1}#panel-berelheto .rb-prem h3{font-size:clamp(22px,2.4vw,28px);font-weight:800;letter-spacing:-.02em;margin:0 0 6px;color:#0b0b0d}#panel-berelheto .rb-prem h3 span{color:#e2001a}#panel-berelheto .rb-prem p{margin:0;color:#5a6b82;font-size:15px;line-height:1.5;max-width:760px}#panel-berelheto .rb-prem ~ .count{display:none}</style>';
        h = h.slice(0, ci) + PREM + h.slice(ci);
        const be2 = h.indexOf('<div class="autok-panel" id="panel-berbeadva">', ci);
        if (be2 > -1) h = h.slice(0, be2) + '<div class="autok-panel" id="panel-premium" hidden></div>\n  ' + h.slice(be2);
        // Prémium raktári autók beolvasztása a modell-kártyákba (BMW X5/X6/X7… darabszám + lista a kártyán)
        try {
          const seg = h.slice(ci, be2 > -1 ? be2 : h.length);
          const de = (x) => String(x || '').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').trim();
          const num = (x) => parseInt(String(x || '').replace(/[^0-9]/g, ''), 10) || 0;
          const STOCK = [];
          const re = /<a class="card[^"]*" href="([^"]*)"([^>]*)>([\s\S]*?)<\/a>/g; let mm;
          while ((mm = re.exec(seg))) {
            const at = mm[2], body = mm[3];
            const ga = (n) => ((at.match(new RegExp(n + '="([^"]*)"')) || [])[1] || '');
            const title = de((body.match(/<h3 class="title">([^<]*)/) || [])[1]);
            if (!title) continue;
            const rows = []; const rr = /<div class="rp"><span>([^<]*)<\/span><b>([^<€]*)€/g; let r2;
            while ((r2 = rr.exec(body))) rows.push([num(r2[1]), num(r2[2])]);
            STOCK.push({
              u: '/' + mm[1].replace(/^(\.\.\/)+/, '').replace(/^\/+/, ''),
              b: de(ga('data-marka')) || title.split(' ')[0], k: de(ga('data-kar')), f: de(ga('data-uz')),
              t: title, y: de((body.match(/<span class="year">([^<]*)/) || [])[1]),
              s: de((body.match(/<div class="specs">([^<]*)/) || [])[1]),
              i: de((body.match(/<img[^>]*?src="([^"]+)"/) || [])[1]),
              r: rows, d: num((body.match(/<div class="rp kau"><span>Kaució<\/span><b>([^<€]*)€/) || [])[1])
            });
          }
          if (STOCK.length) {
            const ins = '<script>window.__ABSTOCK=' + JSON.stringify(STOCK).replace(/</g, '\\u003c') + ';</script>'
              + '<style>#panel-berelheto .rb-prem,#panel-berelheto .rb-prem~.count,#panel-berelheto .rb-prem~.grid{display:none!important}</style>';
            const pa = h.indexOf(ANCHOR) + ANCHOR.length;
            h = h.slice(0, pa) + ins + h.slice(pa);
            console.log('[abo] raktári autók beolvasztva a modell-kártyákba: ' + STOCK.length);
          }
        } catch (e) { console.log('[abo] raktári beolvasztás hiba: ' + e.message); }
        h = h.replace(tabRe, (m, a1, n, c) => a1 + 'Bérelhető (' + SUB_TOTAL + ')' + c +
          '\n      <button class="autok-tab" data-tab="premium" data-group="berles" type="button" hidden>Prémium (' + n + ')</button>');
        h = h.split("(h==='berelheto'||h==='berbeadva')").join("(h==='berelheto'||h==='premium'||h==='berbeadva')");
        h = h.split("heroSwap(b.getAttribute('data-tab'));").join("heroSwap(b.getAttribute('data-tab')==='premium'?'berelheto':b.getAttribute('data-tab'));");
        console.log('[abo] Prémium fül: ' + tm[2] + ' autó, Bérelhető: ' + SUB_TOTAL);
      }
    }
  }
  h = h.replace(/<div class="crate">[^<]*<span id="ratev">([^<]*)<\/span>[^<]*<\/div>/, '<span id="ratev" hidden>$1</span>');
  fs.writeFileSync(f, h);
  done++;
  console.log('[abo] beszurva + hero -> ' + f);
}
console.log('[abo] kesz (' + done + ' fajl modositva)');

// ---- Bérlési modal a modell-oldalakon is (/berelheto-auto/<slug>-berles/) ----
// Ugyanaz a konfigurátor + /api/lead beküldés, mint az /autoink bérelhető kártyáin.
{
  const MODAL_ONLY = '<style>.ab-modal{--red:#E2001A;--navy:#0B0B0D;--ink:#141519;--muted:#5A6B82;--line:#E6EAF1}</style>'
    + STRIP.replace(/<div class="brand-strip"[\s\S]*?<\/div><script>/, '<script>');
  const dir = 'dist/berelheto-auto';
  let n = 0;
  if (fs.existsSync(dir)) {
    for (const sub of fs.readdirSync(dir)) {
      const f = dir + '/' + sub + '/index.html';
      if (!fs.existsSync(f)) continue;
      let h = fs.readFileSync(f, 'utf8');
      if (h.indexOf('sub-rent') < 0 || h.indexOf('window.__ABCFG') > -1) continue;
      const bi = h.lastIndexOf('</body>');
      if (bi < 0) continue;
      h = h.slice(0, bi) + MODAL_ONLY + h.slice(bi);
      fs.writeFileSync(f, h);
      n++;
    }
  }
  console.log('[abo] berlesi modal a modell-oldalakon: ' + n + ' fajl');
}
